#!/usr/bin/env python3
from __future__ import annotations
import sys
from pathlib import Path

def rep(p,o,n,l):
    s=p.read_text(encoding='utf-8'); c=s.count(o)
    if c!=1: raise SystemExit(f'[FAIL] {l}: {c} matches in {p}')
    p.write_text(s.replace(o,n,1),encoding='utf-8'); print('[ok]',l)

def addres(p,n,v):
    s=p.read_text(encoding='utf-8')
    if f'name="{n}"' in s:return
    p.write_text(s.replace('</resources>',f'    <string name="{n}">{v}</string>\n</resources>',1),encoding='utf-8')

def main():
    r=Path(sys.argv[1] if len(sys.argv)>1 else '.').resolve(); w=r/'common/src/main/java/com/shilapi/xcertplay/WheelKeyService.kt'; a=r/'common/src/main/java/com/shilapi/xcertplay/DiPlayActivity.kt'
    rep(w,'    private const val KEY_SIRI = "siri_key"\n    private const val KEY_SIRI_LONG_ONLY = "siri_long_press_only"\n','    private const val KEY_SIRI = "siri_key"\n    private const val KEY_SIRI_LONG_ONLY = "siri_long_press_only"\n    private const val KEY_XINGRUI_MEDIA_PREVIOUS = "xingrui_media_previous"\n    private const val KEY_XINGRUI_MEDIA_NEXT = "xingrui_media_next"\n    private const val KEY_XINGRUI_MEDIA_PLAY_PAUSE = "xingrui_media_play_pause"\n','media pref keys')
    rep(w,'        SELECT(WheelKey(353, 505, BYD_KEYS)),\n        SIRI(null),\n','        SELECT(WheelKey(353, 505, BYD_KEYS)),\n        SIRI(null),\n        MEDIA_PREVIOUS(null),\n        MEDIA_NEXT(null),\n        MEDIA_PLAY_PAUSE(null),\n','media roles')
    rep(w,'    /** Whether any setting needs the key service. */\n    fun anyEnabled(context: Context): Boolean = enabled(context) || joystick(context) || siriKey(context)\n\n    fun isSiriKey(context: Context, key: WheelKey): Boolean = siriKey(context) && key(context, Role.SIRI) == key\n','    private fun hasAssigned(context: Context, role: Role): Boolean = prefs(context).contains("key_${role.name}")\n\n    /** Whether any setting needs the key service. */\n    fun anyEnabled(context: Context): Boolean = enabled(context) || joystick(context) || siriKey(context) ||\n        hasAssigned(context, Role.MEDIA_PREVIOUS) || hasAssigned(context, Role.MEDIA_NEXT) || hasAssigned(context, Role.MEDIA_PLAY_PAUSE)\n\n    fun isSiriKey(context: Context, key: WheelKey): Boolean = siriKey(context) && key(context, Role.SIRI) == key\n    fun isMediaPreviousKey(context: Context, key: WheelKey): Boolean = hasAssigned(context, Role.MEDIA_PREVIOUS) && key(context, Role.MEDIA_PREVIOUS) == key\n    fun isMediaNextKey(context: Context, key: WheelKey): Boolean = hasAssigned(context, Role.MEDIA_NEXT) && key(context, Role.MEDIA_NEXT) == key\n    fun isMediaPlayPauseKey(context: Context, key: WheelKey): Boolean = hasAssigned(context, Role.MEDIA_PLAY_PAUSE) && key(context, Role.MEDIA_PLAY_PAUSE) == key\n','media assignment helpers')
    rep(w,'                Role.SIRI -> siriKey(context)\n                Role.MODE, Role.ZOOM_IN, Role.ZOOM_OUT -> zoom || joystick\n','                Role.SIRI -> siriKey(context)\n                Role.MEDIA_PREVIOUS, Role.MEDIA_NEXT, Role.MEDIA_PLAY_PAUSE -> hasAssigned(context, it)\n                Role.MODE, Role.ZOOM_IN, Role.ZOOM_OUT -> zoom || joystick\n','media conflicts')
    rep(w,'        Role.entries.firstOrNull { it != Role.SIRI && key(context, it) == key }\n','        Role.entries.firstOrNull { it != Role.SIRI && it != Role.MEDIA_PREVIOUS && it != Role.MEDIA_NEXT && it != Role.MEDIA_PLAY_PAUSE && key(context, it) == key }\n','media role lookup')
    rep(w,'            WheelZoomSettings.isSiriKey(this, key) -> WheelZoomSettings.Role.SIRI\n            WheelZoomSettings.anyEnabled(this) -> WheelZoomSettings.roleOf(this, key)\n','            WheelZoomSettings.isSiriKey(this, key) -> WheelZoomSettings.Role.SIRI\n            WheelZoomSettings.isMediaPreviousKey(this, key) -> WheelZoomSettings.Role.MEDIA_PREVIOUS\n            WheelZoomSettings.isMediaNextKey(this, key) -> WheelZoomSettings.Role.MEDIA_NEXT\n            WheelZoomSettings.isMediaPlayPauseKey(this, key) -> WheelZoomSettings.Role.MEDIA_PLAY_PAUSE\n            WheelZoomSettings.anyEnabled(this) -> WheelZoomSettings.roleOf(this, key)\n','recognize media assignments')
    rep(w,'                } ?: siriPress(role, calling, event.eventTime) ?: joystickPress(role, calling)\n','                } ?: xingruiMediaPress(role, calling) ?: siriPress(role, calling, event.eventTime) ?: joystickPress(role, calling)\n','route media assignments')
    rep(w,'    // Without a CarPlay session, or in a call, the key keeps the car\'s own action.\n    private fun siriPress','    private fun xingruiMediaPress(role: WheelZoomSettings.Role?, calling: Boolean): WheelZoomKeys.Action? {\n        if (calling || session() == null) return null\n        val button = when (role) {\n            WheelZoomSettings.Role.MEDIA_PREVIOUS -> CarPlayMediaButton.PREVIOUS\n            WheelZoomSettings.Role.MEDIA_NEXT -> CarPlayMediaButton.NEXT\n            WheelZoomSettings.Role.MEDIA_PLAY_PAUSE -> CarPlayMediaButton.PLAY_PAUSE\n            else -> return null\n        }\n        val sent = CarPlayBackgroundSession.snapshot()?.controller?.sendMediaButton(button) == true\n        note("Xingrui learned media $role sent=$sent")\n        return WheelZoomKeys.Action.CONSUME\n    }\n\n    // Without a CarPlay session, or in a call, the key keeps the car\'s own action.\n    private fun siriPress','CarPlay media HID sender')
    rep(w,'            WheelZoomSettings.Role.JOYSTICK, WheelZoomSettings.Role.SIRI -> Action.PASS\n','            WheelZoomSettings.Role.JOYSTICK, WheelZoomSettings.Role.SIRI,\n            WheelZoomSettings.Role.MEDIA_PREVIOUS, WheelZoomSettings.Role.MEDIA_NEXT, WheelZoomSettings.Role.MEDIA_PLAY_PAUSE -> Action.PASS\n','joystick exhaustive roles')
    rep(w,'            if (!WheelZoomSettings.anyEnabled(service)) return false\n','            val directMedia = role == WheelZoomSettings.Role.MEDIA_PREVIOUS || role == WheelZoomSettings.Role.MEDIA_NEXT || role == WheelZoomSettings.Role.MEDIA_PLAY_PAUSE\n            if (!WheelZoomSettings.anyEnabled(service) && !directMedia) return false\n','first media learn')
    rep(a,'            if (inCall(this) || !WheelZoomSettings.siriKey(this)) {\n','            if (inCall(this) || (learning.role == WheelZoomSettings.Role.SIRI && !WheelZoomSettings.siriKey(this))) {\n','window media learning')
    rep(a,'                (role == WheelZoomSettings.Role.SIRI && learnInWindow(role, cancelled, refused) {\n','                ((role == WheelZoomSettings.Role.SIRI || role == WheelZoomSettings.Role.MEDIA_PREVIOUS || role == WheelZoomSettings.Role.MEDIA_NEXT || role == WheelZoomSettings.Role.MEDIA_PLAY_PAUSE) &&\n                    learnInWindow(role, cancelled, refused) {\n','window learning roles')
    rep(a,'        WheelZoomSettings.Role.SIRI -> R.string.wheel_key_role_siri\n','        WheelZoomSettings.Role.SIRI -> R.string.wheel_key_role_siri\n        WheelZoomSettings.Role.MEDIA_PREVIOUS -> R.string.wheel_key_role_previous\n        WheelZoomSettings.Role.MEDIA_NEXT -> R.string.wheel_key_role_next\n        WheelZoomSettings.Role.MEDIA_PLAY_PAUSE -> R.string.xingrui_wheel_play_pause\n','role labels')
    rep(a,'                WheelZoomSettings.Role.SIRI -> null\n            }.takeIf { joystick }\n','                WheelZoomSettings.Role.SIRI,\n                WheelZoomSettings.Role.MEDIA_PREVIOUS, WheelZoomSettings.Role.MEDIA_NEXT,\n                WheelZoomSettings.Role.MEDIA_PLAY_PAUSE -> null\n            }.takeIf { joystick }\n','joystick label exhaustive roles')
    old='''        section(content, "方控", R.drawable.ic_dp_controls) { card ->\n            card.addView(label("星瑞 E02 方控适配", 17, TEXT, true))\n            card.addView(label("保留上一首、下一首、播放/暂停、音量与 Siri；未识别按键会写入 XingruiWheel 日志。", 14, MUTED).apply { setPadding(0, dp(5), 0, 0) })\n        }\n'''
    new='''        section(content, "方控", R.drawable.ic_dp_controls) { card ->\n            card.addView(label("星瑞 E02 自定义方控", 17, TEXT, true))\n            card.addView(label("点学习后按一下方向盘按键。已学习的切歌键会直接发送给 CarPlay，避免走蓝牙 AVRCP；音量仍交给原车。", 14, MUTED).apply { setPadding(0, dp(5), 0, dp(8)) })\n            wheelKeyServiceControls(card)\n            wheelKeyAssignButton(card, WheelZoomSettings.Role.MEDIA_PREVIOUS, "上一曲")\n            wheelKeyAssignButton(card, WheelZoomSettings.Role.MEDIA_NEXT, "下一曲")\n            wheelKeyAssignButton(card, WheelZoomSettings.Role.MEDIA_PLAY_PAUSE, "播放/暂停")\n            wheelKeyAssignButton(card, WheelZoomSettings.Role.SIRI, "Siri")\n        }\n'''
    rep(a,old,new,'custom wheel UI')
    addres(r/'common/src/main/res/values/strings.xml','xingrui_wheel_play_pause','Play / pause'); zh=r/'common/src/main/res/values-zh-rCN/strings.xml'
    if zh.exists():addres(zh,'xingrui_wheel_play_pause','播放 / 暂停')
    print('Xingrui wheel learning patch applied.')
if __name__=='__main__':main()
